		ArrayList<HISPlayer> playerList = new ArrayList<>();

		public void APL_InitHISPlayer(String hisValue, String unrealContentPath, boolean useRHI, int index)
		{
			try {
				playerList.add(new HISPlayer(this));
				playerList.get(index).init(hisValue, unrealContentPath,useRHI,index);
			} catch (Exception e) {
				System.out.println("HISPLAYER INIT EXCEPTION: " + e.getMessage());
			}
		}

		public boolean APL_AddVideoContent(String url, int index)
		{
			try {
				return playerList.get(index).addVideoContent(url);
			} catch (Exception e) {
				System.out.println("HISPLAYER ADD VIDEO CONTENT EXCEPTION: " + e.getMessage());
				return true;
			}
		}

		public void APL_Play(int index)
		{
			try {
				playerList.get(index).play();	
			} catch (Exception e) {
				System.out.println("HISPLAYER PLAY EXCEPTION: " + e.getMessage());
			}
		}

